    m = len(grid[0]) if n else 0

    zeros = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == 0]
    if not zeros:
        return []

    zr0 = min(r for r, _ in zeros)
    zr1 = max(r for r, _ in zeros)
    zc0 = min(c for _, c in zeros)
    zc1 = max(c for _, c in zeros)

    best = None
    best_map = None

    for pr in range(1, n + 1):
        for pc in range(1, m + 1):
            residue_map = {}
            ok = True
            for r in range(n):
                for c in range(m):
                    v = grid[r][c]
                    if v == 0:
                        continue
                    key = (r % pr, c % pc)
                    if key in residue_map:
                        if residue_map[key] != v:
                            ok = False
                            break
                    else:
                        residue_map[key] = v
                if not ok:
                    break
            if not ok:
                continue

            complete = True
            for r in range(zr0, zr1 + 1):
                for c in range(zc0, zc1 + 1):
                    if (r % pr, c % pc) not in residue_map:
                        complete = False
                        break
                if not complete:
                    break
            if not complete:
                continue

            score = (pr * pc, pr, pc)
            if best is None or score < best:
                best = score
                best_map = residue_map

    if best_map is None:
        return []

    out = []
    for r in range(zr0, zr1 + 1):
        row = []
        for c in range(zc0, zc1 + 1):
            row.append(best_map[(r % best[1], c % best[2])])
        out.append(row)

    return out

